import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    static class Node {
        long key;
        long priority;
        int count;
        int size;
        Node left, right;

        Node(long key, long priority) {
            this.key = key;
            this.priority = priority;
            this.count = 1;
            this.size = 1;
        }
    }

    static long randomState = 0x1234ABCD5678EF90L;

    static long nextRandom() {
        randomState += 0x9E3779B97F4A7C15L;
        long z = randomState;
        z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
        z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
        return z ^ (z >>> 31);
    }

    static int size(Node node) {
        return node == null ? 0 : node.size;
    }

    static void update(Node node) {
        node.size = node.count + size(node.left) + size(node.right);
    }

    static Node rotateRight(Node root) {
        Node next = root.left;
        root.left = next.right;
        next.right = root;
        update(root);
        update(next);
        return next;
    }

    static Node rotateLeft(Node root) {
        Node next = root.right;
        root.right = next.left;
        next.left = root;
        update(root);
        update(next);
        return next;
    }

    static Node insert(Node root, long key) {
        if (root == null) return new Node(key, nextRandom());

        if (key == root.key) {
            root.count++;
        } else if (key < root.key) {
            root.left = insert(root.left, key);
            if (root.left.priority > root.priority) {
                root = rotateRight(root);
            }
        } else {
            root.right = insert(root.right, key);
            if (root.right.priority > root.priority) {
                root = rotateLeft(root);
            }
        }

        update(root);
        return root;
    }

    static int countAtMost(Node root, long key) {
        int result = 0;
        while (root != null) {
            if (key < root.key) {
                root = root.left;
            } else {
                result += size(root.left) + root.count;
                root = root.right;
            }
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = (int) fs.nextLong();

        Node root = null;
        int previousPenalty = 0;
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < n; i++) {
            long x = fs.nextLong() + previousPenalty;
            long y = fs.nextLong() + previousPenalty;
            long distanceSquared = x * x + y * y;

            int penalty = countAtMost(root, distanceSquared);
            out.append(penalty).append('\n');

            root = insert(root, distanceSquared);
            previousPenalty = penalty;
        }

        System.out.print(out);
    }
}
